#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_shardScale;
uniform float amzp_crackWidth;
uniform float amzp_displacement;
uniform float amzp_refraction;
uniform float amzp_crackBrightness;
uniform float amzp_edgeDarken;
uniform float amzp_chromaticAberration;
uniform float amzp_shatterCenterX;
uniform float amzp_shatterCenterY;
uniform float amzp_radialFalloff;
uniform float amzp_portraitContrast;
uniform float amzp_portraitSaturation;
uniform float amzp_showCracksOnly;
uniform float amzp_contentOnly;


        float hash1(float n) {
            return fract(sin(n) * 43758.5453123);
        }

        float hash2f(float2 p) {
            p = fract(p * float2(127.1, 311.7));
            p += dot(p, p + 45.32);
            return fract(p.x * p.y);
        }

        float2 hash2v(float2 p) {
            return float2(
                fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453),
                fract(sin(dot(p, float2(269.5, 183.3))) * 22348.2931)
            );
        }

        float voronoi(float2 p, out float2 cellId, out float secondDist) {
            float2 i = floor(p);
            float2 f = fract(p);
            float minDist = 8.0;
            secondDist = 8.0;
            cellId = float2(0.0);
            for (int y = -2; y <= 2; y++) {
                for (int x = -2; x <= 2; x++) {
                    float2 neighbor = float2(float(x), float(y));
                    float2 point = hash2v(i + neighbor) * 0.8 + 0.1;
                    float2 diff = neighbor + point - f;
                    float d = length(diff);
                    if (d < minDist) {
                        secondDist = minDist;
                        minDist = d;
                        cellId = i + neighbor;
                    } else if (d < secondDist) {
                        secondDist = d;
                    }
                }
            }
            return minDist;
        }

        float crackPattern(float2 p, out float2 cell) {
            float secondD;
            float d = voronoi(p, cell, secondD);
            float border = secondD - d;
            return border;
        }

        float2 getShardDisplacement(float2 cellId, float2 impactCenter, float2 uv) {
            float2 cellCenter = (cellId + hash2v(cellId) * 0.8 + 0.1) / (1.0 / amzp_shardScale);
            float2 fromImpact = cellCenter - impactCenter;
            float distFromImpact = length(fromImpact);
            float falloff = 1.0 - clamp(distFromImpact * amzp_radialFalloff * 2.0, 0.0, 1.0);
            falloff = falloff * falloff;
            float2 randShift = (hash2v(cellId + float2(3.7, 8.1)) - 0.5) * 2.0;
            float2 radialShift = normalize(fromImpact + float2(0.0001)) * 0.3;
            float2 totalShift = (randShift * 0.7 + radialShift * 0.3) * amzp_displacement * falloff;
            return totalShift;
        }

        float4 applyPortraitGrade(float4 color) {
            float luma = dot(color.rgb, float3(0.299, 0.587, 0.114));
            color.rgb = mix(float3(luma), color.rgb, amzp_portraitSaturation);
            color.rgb = (color.rgb - 0.5) * amzp_portraitContrast + 0.5;
            color.rgb = clamp(color.rgb, 0.0, 1.0);
            return color;
        }

        void amzRender() {
            float2 uv = amzLayerNorm();
            float2 impactCenter = float2(amzp_shatterCenterX, amzp_shatterCenterY);

            float distToImpact = length(uv - impactCenter);
            float radialWeight = 1.0 - clamp(distToImpact * amzp_radialFalloff * 1.5, 0.0, 1.0);
            radialWeight = radialWeight * radialWeight;

            float2 scaledUV = uv / amzp_shardScale;
            float2 cellId;
            float borderDist = crackPattern(scaledUV, cellId);

            float crackThreshold = amzp_crackWidth / amzp_shardScale;
            float crackMask = 1.0 - smoothstep(0.0, crackThreshold, borderDist);
            crackMask *= radialWeight;

            float2 shardShift = getShardDisplacement(cellId, impactCenter, uv);

            float2 refractionOffset = float2(0.0);
            if (borderDist < crackThreshold * 3.0) {
                float2 gradX = float2(0.001, 0.0);
                float2 gradY = float2(0.0, 0.001);
                float2 scaledUVx = (uv + gradX) / amzp_shardScale;
                float2 scaledUVy = (uv + gradY) / amzp_shardScale;
                float2 dummyCell;
                float bx = crackPattern(scaledUVx, dummyCell);
                float by = crackPattern(scaledUVy, dummyCell);
                float2 grad = float2(bx - borderDist, by - borderDist) / 0.001;
                refractionOffset = normalize(grad + float2(0.0001)) * amzp_refraction * 0.008 * radialWeight;
            }

            float2 sampleUV = uv + shardShift + refractionOffset;
            sampleUV = (float4(sampleUV, 0.0, 1.0) * amzLayerToScreen()).xy;

            float4 baseColor = amzTexture(0, sampleUV);
            baseColor = applyPortraitGrade(baseColor);

            float ca = amzp_chromaticAberration * 0.006 * radialWeight;
            float2 rOffset = (float4(uv + shardShift + float2(ca, 0.0), 0.0, 1.0) * amzLayerToScreen()).xy;
            float2 bOffset = (float4(uv + shardShift - float2(ca, 0.0), 0.0, 1.0) * amzLayerToScreen()).xy;
            float rChannel = amzTexture(0, rOffset).r;
            float bChannel = amzTexture(0, bOffset).b;
            baseColor.r = mix(baseColor.r, rChannel, amzp_chromaticAberration);
            baseColor.b = mix(baseColor.b, bChannel, amzp_chromaticAberration);

            float edgeShadow = 1.0 - (crackMask * amzp_edgeDarken * (0.3 + radialWeight * 0.7));
            baseColor.rgb *= edgeShadow;

            float3 crackColor = float3(amzp_crackBrightness);
            float specularHighlight = pow(max(0.0, 1.0 - borderDist * 60.0 * amzp_shardScale), 3.0) * radialWeight;
            crackColor += float3(specularHighlight * 0.8);

            float4 finalColor = mix(baseColor, float4(crackColor, baseColor.a), crackMask * 0.85);
            finalColor.a = baseColor.a;

            if ((amzp_showCracksOnly>0.5)) {
                finalColor = float4(float3(crackMask), baseColor.a);
            }

            float4 originalColor = amzTexture(0, amzScreenNorm());

            if ((amzp_contentOnly>0.5)) {
                amzOutput = mix(originalColor, finalColor, originalColor.a);
            } else {
                amzOutput = finalColor;
            }
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

